function detect(text) {
  const normalized = String(text || '').toLowerCase().replace(/\s+/g, ' ');
  const anchors = ["date", "narration", "balance", "withdrawal", "deposit"];
  return anchors.every((anchor) => normalized.includes(anchor));
}

